  const cleanTags = tags.map((tag: string) => {
    const t = tag.trim().toLowerCase().replace(/  +/g, '-')
    if (!t || t === "-") return null
    return t
  }).filter((tag: string) => {
    return tag  
  }).sort()

  const dedupTags = new Set(cleanTags)
  return [...dedupTags]

}

